CREATE TABLE IF NOT EXISTS ai_copilot_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL DEFAULT current_setting('hatchable.user_id', true), strategy_id uuid NULL, strategy_version integer NULL, campaign_id uuid NULL, request_context jsonb NOT NULL DEFAULT '{}'::jsonb, response jsonb NOT NULL DEFAULT '{}'::jsonb, model text NOT NULL DEFAULT 'sonnet', created_at timestamptz NOT NULL DEFAULT now());